-- Упражнения книги 19, глава 3 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 3, 'la3-merge-dropins', 0, 'func', 'Слияние unit-файла и drop-in', 'Напишите функцию merge_dropins(main, dropins): main - текст основного unit-файла, dropins - список пар [имя_файла, текст] (порядок в списке произвольный). Сначала применяется main, потом drop-in в алфавитном порядке имён файлов (обычное сравнение строк); поздний файл побеждает. Разбор: пустые строки и строки, начинающиеся с # или ;, пропускаются; строка [Имя] открывает секцию; остальные строки Ключ=Значение делятся по первому знаку =, пробелы вокруг ключа и значения отбрасываются; строки вне секции и без = игнорируются. Списочные ключи: ExecStart, ExecStartPre, ExecStartPost, ExecStop, Environment, After, Before, Wants, Requires - каждое присваивание добавляет значение (строкой, как написано) в конец списка, а присваивание с пустым значением полностью очищает список. Остальные ключи скалярные: последнее непустое значение побеждает, пустое присваивание удаляет ключ. Верните словарь {секция: {ключ: значение или список}}; пустые списки, удалённые ключи и секции без ключей в результат не попадают.', 'def merge_dropins(main, dropins):
    pass
', 'Одна функция apply(text), вызываемая для main и затем для sorted(dropins). Для списочных ключей пустое значение - это sec[key] = [].', '{"func": "merge_dropins", "tests": [{"args": ["[Unit]\nDescription=A high performance web server\nAfter=network-online.target remote-fs.target\nWants=network-online.target\n\n[Service]\nType=forking\nExecStartPre=/usr/sbin/nginx -t\nExecStart=/usr/sbin/nginx\nRestart=no\nUser=root\n\n[Install]\nWantedBy=multi-user.target\n", []], "expected": {"Unit": {"Description": "A high performance web server", "After": ["network-online.target remote-fs.target"], "Wants": ["network-online.target"]}, "Service": {"Type": "forking", "ExecStartPre": ["/usr/sbin/nginx -t"], "ExecStart": ["/usr/sbin/nginx"], "Restart": "no", "User": "root"}, "Install": {"WantedBy": "multi-user.target"}}}, {"args": ["[Unit]\nDescription=A high performance web server\nAfter=network-online.target remote-fs.target\nWants=network-online.target\n\n[Service]\nType=forking\nExecStartPre=/usr/sbin/nginx -t\nExecStart=/usr/sbin/nginx\nRestart=no\nUser=root\n\n[Install]\nWantedBy=multi-user.target\n", [["override.conf", "[Service]\nRestart=always\nUser=\n"]]], "expected": {"Unit": {"Description": "A high performance web server", "After": ["network-online.target remote-fs.target"], "Wants": ["network-online.target"]}, "Service": {"Type": "forking", "ExecStartPre": ["/usr/sbin/nginx -t"], "ExecStart": ["/usr/sbin/nginx"], "Restart": "always"}, "Install": {"WantedBy": "multi-user.target"}}}, {"args": ["# OpenSSH server\n[Unit]\nDescription=OpenSSH server daemon\nAfter=network.target sshd-keygen.target\nWants=sshd-keygen.target\n\n[Service]\nType=notify\nEnvironmentFile=/etc/sysconfig/sshd\nExecStart=/usr/sbin/sshd -D $OPTIONS\nEnvironment=LANG=C\nRestart=on-failure\n", [["override.conf", "[Service]\nExecStart=\nExecStart=/usr/sbin/sshd -D -e $OPTIONS\n"]]], "expected": {"Unit": {"Description": "OpenSSH server daemon", "After": ["network.target sshd-keygen.target"], "Wants": ["sshd-keygen.target"]}, "Service": {"Type": "notify", "EnvironmentFile": "/etc/sysconfig/sshd", "ExecStart": ["/usr/sbin/sshd -D -e $OPTIONS"], "Environment": ["LANG=C"], "Restart": "on-failure"}}}, {"args": ["# OpenSSH server\n[Unit]\nDescription=OpenSSH server daemon\nAfter=network.target sshd-keygen.target\nWants=sshd-keygen.target\n\n[Service]\nType=notify\nEnvironmentFile=/etc/sysconfig/sshd\nExecStart=/usr/sbin/sshd -D $OPTIONS\nEnvironment=LANG=C\nRestart=on-failure\n", [["20-b.conf", "[Service]\nEnvironment=B=2\n"], ["10-a.conf", "[Service]\nEnvironment=A=1\nRestart=always\n"]]], "expected": {"Unit": {"Description": "OpenSSH server daemon", "After": ["network.target sshd-keygen.target"], "Wants": ["sshd-keygen.target"]}, "Service": {"Type": "notify", "EnvironmentFile": "/etc/sysconfig/sshd", "ExecStart": ["/usr/sbin/sshd -D $OPTIONS"], "Environment": ["LANG=C", "A=1", "B=2"], "Restart": "always"}}}, {"args": ["[Unit]\nAfter=a.service\n", [["10.conf", "[Unit]\nAfter=\n"]]], "expected": {}}, {"args": ["[Service]\nExecStart=/bin/a\n", [["10.conf", "[Service]\nExecStart=\n"], ["20.conf", "[Service]\nExecStart=/bin/b\nExecStart=/bin/c\n"], ["15.conf", "[Service]\nExecStart=/bin/x\n"]]], "expected": {"Service": {"ExecStart": ["/bin/x", "/bin/b", "/bin/c"]}}}, {"args": ["", []], "expected": {}}, {"args": ["stray=1\n# c\n; d\n[Service]\n  Type  =  oneshot  \nbad line\nRemainAfterExit = yes\n", [["a.conf", "[Install]\nWantedBy=multi-user.target\n[Service]\nType=simple\n"]]], "expected": {"Service": {"Type": "simple", "RemainAfterExit": "yes"}, "Install": {"WantedBy": "multi-user.target"}}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 3, 'la3-start-order', 1, 'func', 'Порядок запуска таргета', 'Напишите функцию start_order(units, start): units - словарь имя -> словарь с необязательными ключами "Requires", "Wants", "After", "Before", значения - списки имён юнитов. Сначала найдите набор юнитов транзакции: start и всё, что достижимо от него по Requires и Wants (рекурсивно). Имя, которого нет в units, считается юнитом без зависимостей. Затем упорядочьте набор: если A содержит B в After или B содержит A в Before, то B стартует раньше A; ссылки After/Before на юниты вне набора игнорируются и ничего в набор не добавляют. Верните список имён в порядке запуска; среди готовых к запуску всегда берите юнит с наименьшим именем (обычное сравнение строк). Циклов во входных данных нет.', 'def start_order(units, start):
    pass
', 'Обход в глубину для набора, затем алгоритм Кана: считайте число предшественников и берите минимум из готовых (heapq или min).', '{"func": "start_order", "tests": [{"args": [{"multi-user.target": {"Wants": ["sshd.service", "chronyd.service"], "After": ["basic.target", "sshd.service", "chronyd.service"]}, "sshd.service": {"After": ["network.target", "sshd-keygen.target"], "Wants": ["sshd-keygen.target"]}, "chronyd.service": {"After": ["network.target"]}, "sshd-keygen.target": {}, "basic.target": {}}, "multi-user.target"], "expected": ["chronyd.service", "sshd-keygen.target", "sshd.service", "multi-user.target"]}, {"args": [{"app.service": {"Requires": ["db.service"], "After": ["db.service"]}, "db.service": {"After": ["network.target"], "Wants": ["network.target"]}}, "app.service"], "expected": ["network.target", "db.service", "app.service"]}, {"args": [{"app.service": {"Requires": ["db.service"]}, "db.service": {}}, "app.service"], "expected": ["app.service", "db.service"]}, {"args": [{"a": {"Wants": ["b", "c"]}, "b": {"Before": ["a"]}, "c": {"Before": ["b"]}}, "a"], "expected": ["c", "b", "a"]}, {"args": [{"x": {}}, "x"], "expected": ["x"]}, {"args": [{"t": {"Wants": ["z", "m", "q"]}}, "t"], "expected": ["m", "q", "t", "z"]}, {"args": [{"t": {"Wants": ["a"], "After": ["ghost.service", "other"]}, "other": {}, "a": {"Before": ["other"]}}, "t"], "expected": ["a", "t"]}, {"args": [{"p": {"Requires": ["q"]}, "q": {"Wants": ["r"], "After": ["r"]}, "r": {"After": ["p"]}}, "p"], "expected": ["p", "r", "q"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 3, 'la3-start-result', 2, 'func', 'Чей запуск сорвался', 'Модель запуска с отказами. units, start и правила набора и порядка - как в задаче о порядке запуска: набор юнитов - это start и всё достижимое по Requires и Wants, порядок задают After и Before (если A содержит B в After или B содержит A в Before, B идёт раньше A), среди готовых берётся наименьшее имя. Напишите функцию start_result(units, start, failing): failing - список имён юнитов, которые при запуске сами завершаются отказом. Юниты обрабатываются в порядке запуска. Юнит из failing получает статус "failed". Иначе, если у него есть зависимость r из Requires, которая не получила статус "started" и при этом упорядочена раньше него (по After или Before), он получает статус "skipped" и не запускается. Во всех остальных случаях статус "started": отказ юнита из Wants ничего не меняет, а отказ юнита из Requires без заданного порядка тоже не мешает. Верните словарь имя -> статус для всех юнитов набора. Циклов нет.', 'def start_result(units, start, failing):
    pass
', 'Постройте порядок как в предыдущей задаче, затем идите по нему и ведите словарь статусов. Для проверки порядка нужны оба направления: r в After[u] или u в Before[r].', '{"func": "start_result", "tests": [{"args": [{"app.service": {"Requires": ["db.service"], "After": ["db.service"]}, "db.service": {}}, "app.service", ["db.service"]], "expected": {"db.service": "failed", "app.service": "skipped"}}, {"args": [{"app.service": {"Requires": ["db.service"], "After": ["db.service"]}, "db.service": {}}, "app.service", []], "expected": {"db.service": "started", "app.service": "started"}}, {"args": [{"app.service": {"Requires": ["db.service"]}, "db.service": {}}, "app.service", ["db.service"]], "expected": {"db.service": "failed", "app.service": "started"}}, {"args": [{"app.service": {"Wants": ["cache.service"], "After": ["cache.service"]}, "cache.service": {}}, "app.service", ["cache.service"]], "expected": {"cache.service": "failed", "app.service": "started"}}, {"args": [{"web": {"Requires": ["app"], "After": ["app"]}, "app": {"Requires": ["db"], "After": ["db"]}, "db": {}}, "web", ["db"]], "expected": {"db": "failed", "app": "skipped", "web": "skipped"}}, {"args": [{"web": {"Requires": ["app"], "After": ["app"]}, "app": {"Wants": ["db"], "After": ["db"]}, "db": {}}, "web", ["db"]], "expected": {"db": "failed", "app": "started", "web": "started"}}, {"args": [{"app": {"Requires": ["db"]}, "db": {"Before": ["app"]}}, "app", ["db"]], "expected": {"db": "failed", "app": "skipped"}}, {"args": [{"t": {"Requires": ["a", "b"], "After": ["a", "b"]}, "a": {}, "b": {}}, "t", ["a", "t"]], "expected": {"a": "failed", "b": "started", "t": "failed"}}, {"args": [{"t": {"Requires": ["a", "b"], "After": ["a"]}, "a": {}, "b": {}}, "t", ["b"]], "expected": {"a": "started", "b": "failed", "t": "started"}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 3, 'la3-failed-units', 3, 'func', 'Сводка по list-units', 'Напишите функцию failed_units(text): text - вывод systemctl list-units --all (в том числе с шапкой, пояснениями LOAD/ACTIVE/SUB и итоговой строкой). Строка таблицы - это строка, у которой после необязательной метки в начале (символ ● или *) и пробелов идут поля, разделённые пробелами: имя юнита, LOAD, ACTIVE, SUB и далее описание (описание может отсутствовать). Строкой таблицы считается только строка, где LOAD - одно из loaded, not-found, masked, error, bad-setting, stub, merged, а ACTIVE - одно из active, inactive, failed, activating, deactivating, reloading, maintenance, refreshing. Остальные строки (шапку, пояснения, пустые, итоговые) пропускайте. Верните словарь с двумя ключами: "failed" - отсортированный список имён юнитов с ACTIVE=failed и "counts" - словарь число строк таблицы по каждому встретившемуся значению ACTIVE.', 'def failed_units(text):
    pass
', 'Отбросьте метку: line.lstrip('' ●*''), затем split(). Проверьте длину и допустимые значения во втором и третьем поле.', '{"func": "failed_units", "tests": [{"args": ["  UNIT                               LOAD      ACTIVE   SUB       DESCRIPTION\n  proc-sys-fs-binfmt_misc.automount  loaded    active   waiting   Arbitrary Executable File Formats File System Automount Point\n  cron.service                       loaded    active   running   Regular background program processing daemon\n● demo.service                        loaded    failed   failed    Demo API\n  libvirtd.service                   loaded    active   running   Virtualization daemon\n● nginx.service                       not-found inactive dead      nginx.service\n● postfix.service                     loaded    failed   failed    Postfix Mail Transport Agent\n  ssh.service                        loaded    active   running   OpenBSD Secure Shell server\n  apt-daily.timer                    loaded    active   waiting   Daily apt download activities\n  rescue.service                     loaded    inactive dead      Rescue Shell\n  snapd.service                      masked    inactive dead      snapd.service\n\nLOAD   = Reflects whether the unit definition was properly loaded.\nACTIVE = The high-level unit activation state, i.e. generalization of SUB.\nSUB    = The low-level unit activation state, values depend on unit type.\n10 loaded units listed.\nTo show all installed unit files use ''systemctl list-unit-files''.\n"], "expected": {"failed": ["demo.service", "postfix.service"], "counts": {"active": 5, "failed": 2, "inactive": 3}}}, {"args": ["  UNIT                LOAD   ACTIVE SUB     DESCRIPTION\n  sshd.service        loaded active running OpenSSH server daemon\n* chronyd.service     loaded failed failed  NTP client/server\n* vdsmd.service       loaded failed failed  Virtual Desktop Server Manager\n  crond.service       loaded active running Command Scheduler\n\nLOAD   = Reflects whether the unit definition was properly loaded.\n4 loaded units listed.\n"], "expected": {"failed": ["chronyd.service", "vdsmd.service"], "counts": {"active": 2, "failed": 2}}}, {"args": ["  UNIT              LOAD   ACTIVE SUB     DESCRIPTION\n  dbus.service      loaded active running D-Bus System Message Bus\n  getty@tty1.service loaded active running Getty on tty1\n\n2 loaded units listed.\n"], "expected": {"failed": [], "counts": {"active": 2}}}, {"args": [""], "expected": {"failed": [], "counts": {}}}, {"args": ["  UNIT LOAD ACTIVE SUB DESCRIPTION\nLOAD   = Reflects whether the unit definition was properly loaded.\n0 loaded units listed.\n"], "expected": {"failed": [], "counts": {}}}, {"args": ["● b.mount loaded failed failed\n● a.socket loaded failed failed Socket for a\n  c.path loaded activating start Path c\n"], "expected": {"failed": ["a.socket", "b.mount"], "counts": {"failed": 2, "activating": 1}}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 3, 'la3-parse-status', 4, 'func', 'Разбор systemctl status', 'Напишите функцию parse_status(text): text - вывод systemctl status для одного юнита. Рассматривайте только строки до первой пустой строки (ниже идут строки журнала). Первая строка: необязательная метка состояния (один из символов ● ○ × *), имя юнита и, возможно, " - " с описанием. Остальные строки сравнивайте после удаления начальных пробелов. Строка "Loaded: СОСТОЯНИЕ (...)": первое слово после двоеточия - состояние; внутри скобок поля разделены "; ", enabled - второе поле, если оно есть, иначе пустая строка (у not-found и masked в скобках "Reason: ..." без ";"). Строка "Active: СОСТОЯНИЕ ...": первое слово - состояние, detail - текст первых круглых скобок после него (или пустая строка, если скобок нет). "Main PID: N ..." - целое число N (если строки нет, None). "Memory: X" - первое слово после двоеточия: число, сразу за ним одна буква B, K, M, G или T (степени 1024; для B множитель 1); верните целое число байт, округлив результат умножения (floor(x + 0.5)); если строки нет, None. Остальные строки (Drop-In, Process, CGroup, ...) игнорируйте. Верните словарь с ключами unit, loaded, enabled, active, detail, pid, memory.', 'def parse_status(text):
    pass
', 'Для каждой строки: s = line.strip(); if s.startswith(''Active:'') ... Для скобок используйте find(''('') и find('')''). Для Loaded: содержимое скобок split('';'').', '{"func": "parse_status", "tests": [{"args": ["● nginx.service - A high performance web server and a reverse proxy server\n     Loaded: loaded (/lib/systemd/system/nginx.service; enabled; preset: enabled)\n    Drop-In: /etc/systemd/system/nginx.service.d\n             └─override.conf\n     Active: active (running) since Mon 2026-11-02 08:15:01 UTC; 1 day 2h ago\n       Docs: man:nginx(8)\n    Process: 712 ExecStartPre=/usr/sbin/nginx -t -q -g daemon on; master_process on; (code=exited, status=0/SUCCESS)\n   Main PID: 721 (nginx)\n      Tasks: 3 (limit: 4557)\n     Memory: 5.4M (peak: 6.1M)\n        CPU: 1.204s\n     CGroup: /system.slice/nginx.service\n             ├─721 \"nginx: master process /usr/sbin/nginx -g daemon on; master_process on;\"\n             └─722 \"nginx: worker process\"\n\nNov 02 08:15:01 web1 systemd[1]: Starting nginx.service - A high performance web server...\nNov 02 08:15:01 web1 systemd[1]: Active: this line is from the journal and must be ignored\n"], "expected": {"unit": "nginx.service", "loaded": "loaded", "enabled": "enabled", "active": "active", "detail": "running", "pid": 721, "memory": 5662310}}, {"args": ["× demo.service - Demo API\n     Loaded: loaded (/etc/systemd/system/demo.service; enabled; preset: enabled)\n     Active: failed (Result: exit-code) since Tue 2026-11-03 09:00:12 UTC; 5min ago\n    Process: 4021 ExecStart=/usr/bin/demo --port 8080 (code=exited, status=1/FAILURE)\n   Main PID: 4021 (code=exited, status=1/FAILURE)\n        CPU: 51ms\n"], "expected": {"unit": "demo.service", "loaded": "loaded", "enabled": "enabled", "active": "failed", "detail": "Result: exit-code", "pid": 4021, "memory": null}}, {"args": ["● sshd.service - OpenSSH server daemon\n   Loaded: loaded (/usr/lib/systemd/system/sshd.service; enabled; vendor preset: enabled)\n   Active: active (running) since Fri 2026-10-30 10:00:00 UTC; 4 days ago\n     Docs: man:sshd(8)\n Main PID: 1032 (sshd)\n   CGroup: /system.slice/sshd.service\n           └─1032 /usr/sbin/sshd -D\n"], "expected": {"unit": "sshd.service", "loaded": "loaded", "enabled": "enabled", "active": "active", "detail": "running", "pid": 1032, "memory": null}}, {"args": ["● flaky.service - Flaky worker\n     Loaded: loaded (/etc/systemd/system/flaky.service; disabled; preset: enabled)\n     Active: activating (auto-restart) (Result: exit-code) since Tue 2026-11-03 09:10:00 UTC; 1s ago\n    Process: 99 ExecStart=/usr/bin/flaky (code=exited, status=2/INVALIDARGUMENT)\n   Main PID: 99 (code=exited, status=2/INVALIDARGUMENT)\n     Memory: 1.5G\n"], "expected": {"unit": "flaky.service", "loaded": "loaded", "enabled": "disabled", "active": "activating", "detail": "auto-restart", "pid": 99, "memory": 1610612736}}, {"args": ["○ foo.service\n     Loaded: not-found (Reason: Unit foo.service not found.)\n     Active: inactive (dead)\n"], "expected": {"unit": "foo.service", "loaded": "not-found", "enabled": "", "active": "inactive", "detail": "dead", "pid": null, "memory": null}}, {"args": ["○ snapd.service\n     Loaded: masked (Reason: Unit snapd.service is masked.)\n     Active: inactive (dead)\n"], "expected": {"unit": "snapd.service", "loaded": "masked", "enabled": "", "active": "inactive", "detail": "dead", "pid": null, "memory": null}}, {"args": ["● x.service\n   Loaded: loaded (/etc/systemd/system/x.service; static)\n   Active: active (exited) since Mon\n   Memory: 900B\n"], "expected": {"unit": "x.service", "loaded": "loaded", "enabled": "static", "active": "active", "detail": "exited", "pid": null, "memory": 900}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 3, 'la3-next-elapse', 5, 'func', 'Следующее срабатывание OnCalendar', 'Напишите функцию next_elapse(spec, now): spec - выражение OnCalendar, now - момент "YYYY-MM-DD HH:MM:SS" (всё в UTC, переходов времени нет). Верните ближайший момент строго после now, на который выражение срабатывает, в том же формате, или пустую строку, если его нет в ближайших 9 годах. Сокращения (без учёта регистра): minutely = *-*-* *:*:00, hourly = *-*-* *:00:00, daily = *-*-* 00:00:00, weekly = Mon *-*-* 00:00:00, monthly = *-*-01 00:00:00, yearly = *-01-01 00:00:00. Иначе выражение состоит из до трёх слов в любом порядке: день недели (содержит только буквы, точки и запятые), дата (содержит -) и время (содержит :). Нет даты: *-*-*; нет времени: 00:00:00; в времени без секунд секунды равны 00; в дате из двух частей год равен *. Поля год, месяц, день, час, минута, секунда: * - любое значение; список через запятую; значение a; диапазон a..b; шаг /n: a/n означает a, a+n, ... до максимума поля, a..b/n - от a до b с шагом n, */n - от минимума поля с шагом n. Минимумы и максимумы: месяц 1-12, день 1-31, час 0-23, минута и секунда 0-59. День недели: имена Mon..Sun (регистр не важен, достаточно первых трёх букв), список через запятую и диапазон Mon..Fri; если указан, день должен подходить. Дней, которых нет в месяце, не существует (31 ноября, 29 февраля не високосного года).', 'def next_elapse(spec, now):
    pass
', 'Разберите поле в множество чисел; затем перебирайте дни с сегодняшнего (до 9*366) и для первого дня ищите первое время строго больше now, для следующих берите самое раннее.', '{"func": "next_elapse", "tests": [{"args": ["daily", "2026-11-03 10:15:00"], "expected": "2026-11-04 00:00:00"}, {"args": ["daily", "2026-11-03 00:00:00"], "expected": "2026-11-04 00:00:00"}, {"args": ["weekly", "2026-11-03 10:15:00"], "expected": "2026-11-09 00:00:00"}, {"args": ["Mon..Fri 09:00", "2026-11-06 18:00:00"], "expected": "2026-11-09 09:00:00"}, {"args": ["Mon..Fri 09:00", "2026-11-04 08:59:59"], "expected": "2026-11-04 09:00:00"}, {"args": ["*-*-1,15 12:00", "2026-11-03 10:00:00"], "expected": "2026-11-15 12:00:00"}, {"args": ["*:0/15", "2026-11-03 10:15:00"], "expected": "2026-11-03 10:30:00"}, {"args": ["*:0/15", "2026-11-03 23:50:00"], "expected": "2026-11-04 00:00:00"}, {"args": ["*-02-29 00:00:00", "2026-11-03 10:00:00"], "expected": "2028-02-29 00:00:00"}, {"args": ["*-*-31 12:00", "2026-11-03 10:00:00"], "expected": "2026-12-31 12:00:00"}, {"args": ["Sat,Sun *-*-* 03:00", "2026-11-03 10:00:00"], "expected": "2026-11-07 03:00:00"}, {"args": ["*-*-* 4,16:00", "2026-11-03 10:00:00"], "expected": "2026-11-03 16:00:00"}, {"args": ["monthly", "2026-12-15 08:00:00"], "expected": "2027-01-01 00:00:00"}, {"args": ["2020-01-01 00:00:00", "2026-11-03 10:00:00"], "expected": ""}, {"args": ["2026-12-25", "2026-11-03 10:00:00"], "expected": "2026-12-25 00:00:00"}, {"args": ["hourly", "2026-11-03 10:59:59"], "expected": "2026-11-03 11:00:00"}, {"args": ["*-*-* 02..04:00/30", "2026-11-03 02:00:00"], "expected": "2026-11-03 02:30:00"}, {"args": ["Thu *-*-13 00:00:00", "2026-11-03 10:00:00"], "expected": "2027-05-13 00:00:00"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 3, 'la3-restart-sim', 6, 'func', 'Симуляция Restart= и StartLimit', 'Напишите функцию restart_sim(policy, restart_sec, burst, interval, runs): модель службы с политикой перезапуска. Первый запуск происходит в момент 0 (целые секунды). runs[i] - пара [длительность, исход] i-го запуска, исход: "clean" (выход с кодом 0), "failure" (ненулевой код), "signal" (аварийный сигнал), "timeout", "watchdog". После окончания запуска (момент старта + длительность) политика решает, перезапускать ли службу: no - никогда; always - всегда; on-success - только после clean; on-failure - после failure, signal, timeout, watchdog; on-abnormal - после signal, timeout, watchdog; on-abort - только после signal; on-watchdog - только после watchdog. Если решено перезапускать, новый запуск происходит через restart_sec секунд после окончания. Ограничение частоты: окно начинается при первом запуске и сдвигается так: перед каждым запуском в момент t, если окна ещё нет или t - начало окна > interval, начинается новое окно с началом t и счётчиком 1; иначе счётчик растёт на 1 и, если стал больше burst, запуск запрещён. Если interval равен 0, ограничения нет. Верните кортеж (список моментов всех состоявшихся запусков, итог): "stopped" - политика не велела перезапускать после последнего прошедшего запуска; "start-limit-hit" - очередной запуск запрещён; "running" - запуски кончились раньше, чем данные runs (для последнего запуска сведений о завершении нет). То есть после запуска номер i при i >= len(runs) возвращайте "running".', 'def restart_sim(policy, restart_sec, burst, interval, runs):
    pass
', 'Цикл: проверить окно, записать момент запуска, если данных нет - выйти с running, иначе решить по политике и сдвинуть t на длительность + restart_sec.', '{"func": "restart_sim", "tests": [{"args": ["on-failure", 1, 5, 10, [[1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"]]], "expected": {"__tuple__": [[0, 2, 4, 6, 8], "start-limit-hit"]}}, {"args": ["on-failure", 1, 5, 10, [[1, "failure"], [1, "failure"], [1, "failure"]]], "expected": {"__tuple__": [[0, 2, 4, 6], "running"]}}, {"args": ["on-failure", 2, 3, 10, [[1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"]]], "expected": {"__tuple__": [[0, 3, 6], "start-limit-hit"]}}, {"args": ["on-failure", 1, 3, 10, [[0, "failure"], [1, "clean"]]], "expected": {"__tuple__": [[0, 1], "stopped"]}}, {"args": ["on-abnormal", 1, 5, 10, [[3, "failure"]]], "expected": {"__tuple__": [[0], "stopped"]}}, {"args": ["on-abnormal", 1, 5, 10, [[3, "signal"], [3, "timeout"]]], "expected": {"__tuple__": [[0, 4, 8], "running"]}}, {"args": ["always", 1, 5, 10, [[20, "clean"], [20, "clean"], [20, "clean"]]], "expected": {"__tuple__": [[0, 21, 42, 63], "running"]}}, {"args": ["on-success", 1, 5, 10, [[5, "failure"]]], "expected": {"__tuple__": [[0], "stopped"]}}, {"args": ["on-success", 1, 5, 10, [[5, "clean"], [5, "clean"]]], "expected": {"__tuple__": [[0, 6, 12], "running"]}}, {"args": ["no", 1, 5, 10, [[5, "failure"]]], "expected": {"__tuple__": [[0], "stopped"]}}, {"args": ["always", 1, 2, 0, [[0, "failure"], [0, "failure"], [0, "failure"], [0, "failure"], [0, "failure"], [0, "failure"]]], "expected": {"__tuple__": [[0, 1, 2, 3, 4, 5, 6], "running"]}}, {"args": ["always", 5, 2, 10, [[1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"], [1, "failure"]]], "expected": {"__tuple__": [[0, 6, 12, 18, 24, 30, 36], "running"]}}, {"args": ["on-watchdog", 1, 5, 10, [[1, "watchdog"], [1, "signal"]]], "expected": {"__tuple__": [[0, 2], "stopped"]}}, {"args": ["on-abort", 1, 5, 10, [[1, "signal"], [1, "watchdog"]]], "expected": {"__tuple__": [[0, 2], "stopped"]}}, {"args": ["always", 0, 3, 10, [[2, "failure"], [2, "failure"], [2, "failure"], [2, "failure"], [2, "failure"], [2, "failure"], [2, "failure"], [2, "failure"]]], "expected": {"__tuple__": [[0, 2, 4], "start-limit-hit"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 3, 'la3-blame-top', 7, 'func', 'Самые долгие юниты по blame', 'Напишите функцию blame_top(text, n): text - вывод systemd-analyze blame: в каждой строке сначала время запуска из одного или нескольких слов вида число+единица (h, min, s, ms, us; число может быть дробным, например "1min 3.254s", "843ms", "1h 2min 3.5s"), а последнее слово - имя юнита. Переведите время в целые миллисекунды (сумма слагаемых; каждое слагаемое число * множитель, где h = 3600000, min = 60000, s = 1000, ms = 1, us = 0.001; итог округлите как floor(x + 0.5)). Пропускайте пустые строки и строки, в которых не нашлось ни одного слова-времени. Верните список из n самых долгих юнитов в виде кортежей (имя, миллисекунды), по убыванию времени, а при равенстве - по имени по возрастанию. Если юнитов меньше n, верните все.', 'def blame_top(text, n):
    pass
', 'Регулярка r''^(\d+(?:\.\d+)?)(h|min|s|ms|us)$'' на каждое слово кроме последнего; ключ сортировки (-мс, имя).', '{"func": "blame_top", "tests": [{"args": ["         1min 3.254s apt-daily.service\n         12.309s cloud-init-local.service\n          6.514s snapd.seeded.service\n          2.101s libvirtd.service\n           843ms networkd-dispatcher.service\n           843ms keyboard-setup.service\n            12ms sys-kernel-config.mount\n", 3], "expected": [{"__tuple__": ["apt-daily.service", 63254]}, {"__tuple__": ["cloud-init-local.service", 12309]}, {"__tuple__": ["snapd.seeded.service", 6514]}]}, {"args": ["         1min 3.254s apt-daily.service\n         12.309s cloud-init-local.service\n          6.514s snapd.seeded.service\n          2.101s libvirtd.service\n           843ms networkd-dispatcher.service\n           843ms keyboard-setup.service\n            12ms sys-kernel-config.mount\n", 10], "expected": [{"__tuple__": ["apt-daily.service", 63254]}, {"__tuple__": ["cloud-init-local.service", 12309]}, {"__tuple__": ["snapd.seeded.service", 6514]}, {"__tuple__": ["libvirtd.service", 2101]}, {"__tuple__": ["keyboard-setup.service", 843]}, {"__tuple__": ["networkd-dispatcher.service", 843]}, {"__tuple__": ["sys-kernel-config.mount", 12]}]}, {"args": ["         1min 3.254s apt-daily.service\n         12.309s cloud-init-local.service\n          6.514s snapd.seeded.service\n          2.101s libvirtd.service\n           843ms networkd-dispatcher.service\n           843ms keyboard-setup.service\n            12ms sys-kernel-config.mount\n", 0], "expected": []}, {"args": ["      1h 2min 3.5s backup-restore.service\n         59.999s slow.service\n       1min 0.5s other.service\n            7us tiny.service\n", 4], "expected": [{"__tuple__": ["backup-restore.service", 3723500]}, {"__tuple__": ["other.service", 60500]}, {"__tuple__": ["slow.service", 59999]}, {"__tuple__": ["tiny.service", 0]}]}, {"args": ["", 5], "expected": []}, {"args": ["\n   12ms a.service\nnot a time line here\n   3ms b.service\n", 1], "expected": [{"__tuple__": ["a.service", 12]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 3, 'la3-chain-report', 8, 'func', 'Разбор critical-chain', 'Напишите функцию chain_report(text): text - вывод systemd-analyze critical-chain для цели. Строка цепочки имеет вид "[символы дерева]ИМЯ @ВРЕМЯ" или "[символы дерева]ИМЯ @ВРЕМЯ +ДЛИТЕЛЬНОСТЬ", где символы дерева - любые из пробела, │, ├, └, ─; ИМЯ - слово без пробелов; ВРЕМЯ и ДЛИТЕЛЬНОСТЬ - время из слов вида число+единица (h, min, s, ms, us, число может быть дробным, части разделены пробелом, например "1min 2.000s"). Остальные строки (пояснение, пустые) пропускайте: цепочку образуют только строки, где после имени и пробела стоит @, а за ним цифра. Каждая следующая строка цепочки - зависимость предыдущей. Переводите время в целые миллисекунды как floor(сумма + 0.5) (h = 3600000, min = 60000, s = 1000, ms = 1, us = 0.001). Для строки без + длительность равна 0. @ - момент начала запуска юнита; юнит из следующей строки (зависимость) завершил запуск в момент @ + длительность этой следующей строки. Простой строки i - это max(0, @(i) - (@(i+1) + длит(i+1))), то есть сколько юнит ждал зависимость после её завершения; для последней строки простоя нет. Верните кортеж (имя юнита с наибольшей длительностью (при равенстве - выше в списке), сумма простоев в миллисекундах). Для пустой цепочки верните ("", 0).', 'def chain_report(text):
    pass
', 'Отрежьте символы дерева lstrip('' │├└─''), затем найдите '' @'' и необязательное '' +''. Время разбирайте теми же словами число+единица, что и в blame.', '{"func": "chain_report", "tests": [{"args": ["The time when unit became active or started is printed after the \"@\" character.\nThe time the unit took to start is printed after the \"+\" character.\n\ngraphical.target @12.531s\n└─multi-user.target @12.531s\n  └─vdsmd.service @8.220s +4.298s\n    └─libvirtd.service @6.001s +2.200s\n      └─network-online.target @5.990s\n        └─NetworkManager-wait-online.service @3.600s +2.389s\n          └─NetworkManager.service @3.200s +390ms\n            └─dbus.service @3.100s\n"], "expected": {"__tuple__": ["vdsmd.service", 154]}}, {"args": ["multi-user.target @2.000s\n└─cron.service @1.500s +400ms\n  └─basic.target @1.400s\n"], "expected": {"__tuple__": ["cron.service", 200]}}, {"args": ["multi-user.target @1min 10.000s\n└─slow.service @1min 2.000s +8.000s\n  └─net.service @10.000s +50.000s\n"], "expected": {"__tuple__": ["net.service", 2000]}}, {"args": [""], "expected": {"__tuple__": ["", 0]}}, {"args": ["graphical.target @5.000s\n"], "expected": {"__tuple__": ["graphical.target", 0]}}, {"args": ["a.target @10.000s\n└─b.service @3.000s +2.000s\n  └─c.service @1.000s +500ms\n"], "expected": {"__tuple__": ["b.service", 6500]}}, {"args": ["x @1s +1s\ny @1s +1s\n"], "expected": {"__tuple__": ["x", 0]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 3, 'la3-exec-line', 9, 'func', 'Префиксы ExecStart', 'Напишите функцию exec_line(line): line - значение ExecStart=. В его начале может стоять любое число символов-префиксов: @ (следующее слово после пути - argv[0]), - (код ошибки команды игнорируется), : (подстановка переменных окружения отключена), + (полные привилегии), ! (повышаются только User=, Group= и SupplementaryGroups=); сочетайте их в любом порядке без пробелов, одновременно + и ! не встречаются. Всё после префиксов делится по пробелам (кавычек нет): первое слово - путь к программе, остальные - слова команды. Верните словарь: path - путь; argv - список аргументов процесса: без @ это [путь] + остальные слова, с @ это остальные слова как есть (первое из них - argv[0]), а если слов после пути нет - [путь]; ignore_failure - True, если был префикс -; no_expand - True, если был префикс :; privilege - "full" для +, "user" для !, иначе "normal".', 'def exec_line(line):
    pass
', 'Снимайте символы из множества ''@-:+!'' с начала строки в цикле и ведите флаги; потом line.split().', '{"func": "exec_line", "tests": [{"args": ["/usr/sbin/nginx -g daemon off;"], "expected": {"path": "/usr/sbin/nginx", "argv": ["/usr/sbin/nginx", "-g", "daemon", "off;"], "ignore_failure": false, "no_expand": false, "privilege": "normal"}}, {"args": ["-/usr/bin/rm -f /run/demo.pid"], "expected": {"path": "/usr/bin/rm", "argv": ["/usr/bin/rm", "-f", "/run/demo.pid"], "ignore_failure": true, "no_expand": false, "privilege": "normal"}}, {"args": ["+/usr/bin/chown demo /run/demo"], "expected": {"path": "/usr/bin/chown", "argv": ["/usr/bin/chown", "demo", "/run/demo"], "ignore_failure": false, "no_expand": false, "privilege": "full"}}, {"args": ["@/usr/bin/sleep mysleep 10"], "expected": {"path": "/usr/bin/sleep", "argv": ["mysleep", "10"], "ignore_failure": false, "no_expand": false, "privilege": "normal"}}, {"args": ["@/usr/bin/true"], "expected": {"path": "/usr/bin/true", "argv": ["/usr/bin/true"], "ignore_failure": false, "no_expand": false, "privilege": "normal"}}, {"args": ["-:!/bin/echo $HOME"], "expected": {"path": "/bin/echo", "argv": ["/bin/echo", "$HOME"], "ignore_failure": true, "no_expand": true, "privilege": "user"}}, {"args": ["!-@/bin/prog name a b"], "expected": {"path": "/bin/prog", "argv": ["name", "a", "b"], "ignore_failure": true, "no_expand": false, "privilege": "user"}}, {"args": ["/bin/true"], "expected": {"path": "/bin/true", "argv": ["/bin/true"], "ignore_failure": false, "no_expand": false, "privilege": "normal"}}]}');
